    upstreamType: "IP_PORT",
    retries: 5,
    nodes: [{
        host: "1.1.1.1",
        port: 9090,
        weight: 10,
        vmInstanceId: example.id,
        tags: ["tags"],
    }],
    tags: {
        createdBy: "terraform",
    },
});
