tencentcloud:As/attachment:Attachment.description:
Provides a resource to attach or detach CVM instances to a specified scaling group.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const zones = tencentcloud.availability.getZonesByProduct({
    product: "as",
});
const image = tencentcloud.images.getInstance({
    imageTypes: ["PUBLIC_IMAGE"],
    osName: "TencentOS Server 3.2 (Final)",
});
const instanceTypes = zones.then(zones => tencentcloud.instance.getTypes({
    filters: [
        {
            name: "zone",
            values: [zones.zones?.[0]?.name],
        },
        {
            name: "instance-family",
            values: ["S5"],
        },
    ],
    cpuCoreCount: 2,
    excludeSoldOut: true,
}));
const vpc = new tencentcloud.vpc.Instance("vpc", {
    name: "vpc-example",
    cidrBlock: "10.0.0.0/16",
});
const subnet = new tencentcloud.subnet.Instance("subnet", {
    vpcId: vpc.id,
    name: "subnet-example",
    cidrBlock: "10.0.0.0/16",
    availabilityZone: zones.then(zones => zones.zones?.[0]?.name),
});
const example = new tencentcloud.as.ScalingConfig("example", {
    configurationName: "tf-example",
    imageId: image.then(image => image.images?.[0]?.imageId),
    instanceTypes: [
        "SA1.SMALL1",
        "SA2.SMALL1",
        "SA2.SMALL2",
        "SA2.SMALL4",
    ],
    instanceNameSettings: {
        instanceName: "test-ins-name",
    },
});
const exampleScalingGroup = new tencentcloud.as.ScalingGroup("example", {
    scalingGroupName: "tf-example",
    configurationId: example.id,
    maxSize: 1,
    minSize: 0,
    vpcId: vpc.id,
    subnetIds: [subnet.id],
});
const exampleInstance = new tencentcloud.instance.Instance("example", {
    instanceName: "tf_example_instance",
    availabilityZone: zones.then(zones => zones.zones?.[0]?.name),
    imageId: image.then(image => image.images?.[0]?.imageId),
    instanceType: instanceTypes.then(instanceTypes => instanceTypes.instanceTypes?.[0]?.instanceType),
    systemDiskType: "CLOUD_PREMIUM",
    systemDiskSize: 50,
    allocatePublicIp: true,
    internetMaxBandwidthOut: 10,
    vpcId: vpc.id,
    subnetId: subnet.id,
});
const attachment = new tencentcloud.as.Attachment("attachment", {
    scalingGroupId: exampleScalingGroup.id,
    instanceIds: [exampleInstance.id],
});
