## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const config = new pulumi.Config();
const availabilityZone = config.get("availabilityZone") || "ap-guangzhou-6";
// create vpc
const vpc = new tencentcloud.vpc.Instance("vpc", {
    cidrBlock: "10.0.0.0/16",
    name: "vpc",
});
// create subnet
const subnet = new tencentcloud.subnet.Instance("subnet", {
    vpcId: vpc.id,
    availabilityZone: availabilityZone,
    name: "subnet",
    cidrBlock: "10.0.1.0/24",
    isMulticast: false,
});
const example = new tencentcloud.as.ScalingConfig("example", {
    configurationName: "tf-example",
    imageId: "img-eb30mz89",
    instanceTypes: ["S6.MEDIUM4"],
    instanceNameSettings: {
        instanceName: "demo-ins-name",
    },
});
const exampleScalingGroup = new tencentcloud.as.ScalingGroup("example", {
    scalingGroupName: "tf-example",
    configurationId: example.id,
    maxSize: 1,
    minSize: 0,
    vpcId: vpc.id,
    subnetIds: [subnet.id],
});
const exampleInstance = new tencentcloud.clb.Instance("example", {
    networkType: "INTERNAL",
    clbName: "tf-example",
    vpcId: vpc.id,
    subnetId: subnet.id,
    tags: {
        createBy: "Terraform",
    },
});
const exampleListener = new tencentcloud.clb.Listener("example", {
    clbId: exampleInstance.id,
    listenerName: "tf-example",
    port: 80,
    protocol: "HTTP",
});
const exampleListenerRule = new tencentcloud.clb.ListenerRule("example", {
    listenerId: exampleListener.listenerId,
    clbId: exampleInstance.id,
    domain: "foo.net",
    url: "/bar",
});
const exampleLoadBalancer = new tencentcloud.as.LoadBalancer("example", {
    autoScalingGroupId: exampleScalingGroup.id,
    forwardLoadBalancers: [{
        loadBalancerId: exampleInstance.id,
        listenerId: exampleListener.listenerId,
        locationId: exampleListenerRule.ruleId,
        targetAttributes: [{
            port: 8080,
            weight: 20,
        }],
    }],
});
