			return err
		}
		exampleScalingGroup, err := as.NewScalingGroup(ctx, "example", &as.ScalingGroupArgs{
			ScalingGroupName: pulumi.String("tf-example"),
			ConfigurationId:  example.ID().ToIDOutput().ToStringOutput(),
			MaxSize:          pulumi.Int(1),
