package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi/config"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/ccn"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/subnet"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/vpc"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		region := "ap-guangzhou"
		if param := cfg.Get("region"); param != "" {
			region = param
		}
		availabilityZone := "ap-guangzhou-4"
		if param := cfg.Get("availabilityZone"); param != "" {
			availabilityZone = param
		}
		// create vpc
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc"),
			CidrBlock: pulumi.String("172.16.0.0/16"),
		})
		if err != nil {
			return err
		}
		// create subnet
		_, err = subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			AvailabilityZone: pulumi.String(availabilityZone),
			Name:             pulumi.String("subnet"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("172.16.0.0/24"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create ccn
		example, err := ccn.NewInstance(ctx, "example", &ccn.InstanceArgs{
			Name:               pulumi.String("tf-example"),
			Description:        pulumi.String("desc."),
			Qos:                pulumi.String("AG"),
			ChargeType:         pulumi.String("PREPAID"),
			BandwidthLimitType: pulumi.String("INTER_REGION_LIMIT"),
			Tags: pulumi.StringMap{
				"createBy": pulumi.String("terraform"),
			},
		})
		if err != nil {
			return err
		}
		// create ccn route table
		exampleRouteTable, err := ccn.NewRouteTable(ctx, "example", &ccn.RouteTableArgs{
			CcnId:       example.ID().ToIDOutput().ToStringOutput(),
			Name:        pulumi.String("tf-example"),
			Description: pulumi.String("desc."),
		})
		if err != nil {
			return err
		}
		// attachment instance
		_, err = tencentcloud.NewCcnAttachment(ctx, "attachment", &tencentcloud.CcnAttachmentArgs{
			CcnId:          example.ID(),
			InstanceId:     vpc2.ID(),
			InstanceType:   "VPC",
			InstanceRegion: region,
			RouteTableId:   exampleRouteTable.ID(),
		})
		if err != nil {
			return err
		}
		// create route table broadcast policy
		_, err = ccn.NewRouteTableBroadcastPolicies(ctx, "example", &ccn.RouteTableBroadcastPoliciesArgs{
			CcnId:        example.ID().ToIDOutput().ToStringOutput(),
			RouteTableId: exampleRouteTable.ID().ToIDOutput().ToStringOutput(),
			Policies: ccn.RouteTableBroadcastPoliciesPolicyArray{
				&ccn.RouteTableBroadcastPoliciesPolicyArgs{
					Action:      pulumi.String("accept"),
					Description: pulumi.String("desc."),
					RouteConditions: ccn.RouteTableBroadcastPoliciesPolicyRouteConditionArray{
						&ccn.RouteTableBroadcastPoliciesPolicyRouteConditionArgs{
							Name: pulumi.String("instance-region"),
							Values: pulumi.StringArray{
								pulumi.String("ap-guangzhou"),
							},
							MatchPattern: pulumi.Int(1),
						},
					},
					BroadcastConditions: ccn.RouteTableBroadcastPoliciesPolicyBroadcastConditionArray{
						&ccn.RouteTableBroadcastPoliciesPolicyBroadcastConditionArgs{
							Name: pulumi.String("instance-region"),
							Values: pulumi.StringArray{
								pulumi.String("ap-shanghai"),
							},
							MatchPattern: pulumi.Int(1),
						},
					},
				},
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
