> **NOTE:** To use this resource, The <span pulumi-lang-nodejs="`workloadGroupStatus`" pulumi-lang-dotnet="`WorkloadGroupStatus`" pulumi-lang-go="`workloadGroupStatus`" pulumi-lang-python="`workload_group_status`" pulumi-lang-yaml="`workloadGroupStatus`" pulumi-lang-java="`workloadGroupStatus`" pulumi-lang-hcl="`workload_group_status`">`workloadGroupStatus`</span> field of <span pulumi-lang-nodejs="`tencentcloud.Cdwdoris.Instance`" pulumi-lang-dotnet="`tencentcloud.Cdwdoris.Instance`" pulumi-lang-go="`Cdwdoris.Instance`" pulumi-lang-python="`Cdwdoris.Instance`" pulumi-lang-yaml="`tencentcloud.Cdwdoris.Instance`" pulumi-lang-java="`tencentcloud.Cdwdoris.Instance`" pulumi-lang-hcl="`tencentcloud_cdwdoris_instance`">`tencentcloud.Cdwdoris.Instance`</span> needs to be set to true.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const config = new pulumi.Config();
const availabilityZone = config.get("availabilityZone") || "ap-guangzhou-6";
// create vpc
const vpc = new tencentcloud.vpc.Instance("vpc", {
    name: "vpc",
    cidrBlock: "172.16.0.0/16",
});
// create subnet
const subnet = new tencentcloud.subnet.Instance("subnet", {
    availabilityZone: availabilityZone,
    name: "subnet",
    vpcId: vpc.id,
    cidrBlock: "172.16.0.0/24",
    isMulticast: false,
});
// create instance
const example = new tencentcloud.cdwdoris.Instance("example", {
    zone: availabilityZone,
    userVpcId: vpc.id,
    userSubnetId: subnet.id,
    productVersion: "2.1",
    instanceName: "tf-example",
    dorisUserPwd: "Password@test",
    haFlag: false,
    caseSensitive: 0,
    enableMultiZones: false,
    workloadGroupStatus: "open",
    chargeProperties: {
        chargeType: "POSTPAID_BY_HOUR",
    },
    feSpec: {
        specName: "S_4_16_P",
        count: 3,
        diskSize: 200,
    },
    beSpec: {
        specName: "S_4_16_P",
        count: 3,
        diskSize: 200,
    },
    tags: [{
        tagKey: "createBy",
        tagValue: "Terraform",
    }],
});
// create workload group
const exampleWorkloadGroup = new tencentcloud.cdwdoris.WorkloadGroup("example", {
    instanceId: example.id,
    workloadGroup: {
        workloadGroupName: "example",
        cpuShare: 1024,
        memoryLimit: 20,
        enableMemoryOverCommit: true,
        cpuHardLimit: "30%",
    },
});
