```go
package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi/config"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/cdwdoris"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/subnet"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/vpc"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		availabilityZone := "ap-guangzhou-6"
		if param := cfg.Get("availabilityZone"); param != "" {
			availabilityZone = param
		}
		// create vpc
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc"),
			CidrBlock: pulumi.String("172.16.0.0/16"),
		})
		if err != nil {
			return err
		}
		// create subnet
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			AvailabilityZone: pulumi.String(availabilityZone),
			Name:             pulumi.String("subnet"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("172.16.0.0/24"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create instance
		example, err := cdwdoris.NewInstance(ctx, "example", &cdwdoris.InstanceArgs{
			Zone:                pulumi.String(availabilityZone),
			UserVpcId:           vpc2.ID().ToIDOutput().ToStringOutput(),
			UserSubnetId:        subnet2.ID().ToIDOutput().ToStringOutput(),
			ProductVersion:      pulumi.String("2.1"),
			InstanceName:        pulumi.String("tf-example"),
			DorisUserPwd:        pulumi.String("Password@test"),
			HaFlag:              pulumi.Bool(false),
			CaseSensitive:       pulumi.Int(0),
			EnableMultiZones:    pulumi.Bool(false),
			WorkloadGroupStatus: pulumi.String("open"),
			ChargeProperties: &cdwdoris.InstanceChargePropertiesArgs{
				ChargeType: pulumi.String("POSTPAID_BY_HOUR"),
			},
			FeSpec: &cdwdoris.InstanceFeSpecArgs{
				SpecName: pulumi.String("S_4_16_P"),
				Count:    pulumi.Int(3),
				DiskSize: pulumi.Int(200),
			},
			BeSpec: &cdwdoris.InstanceBeSpecArgs{
				SpecName: pulumi.String("S_4_16_P"),
				Count:    pulumi.Int(3),
				DiskSize: pulumi.Int(200),
			},
			Tags: cdwdoris.InstanceTagArray{
				&cdwdoris.InstanceTagArgs{
					TagKey:   pulumi.String("createBy"),
					TagValue: pulumi.String("Terraform"),
				},
			},
		})
		if err != nil {
			return err
		}
		// create workload group
		_, err = cdwdoris.NewWorkloadGroup(ctx, "example", &cdwdoris.WorkloadGroupArgs{
			InstanceId: example.ID().ToIDOutput().ToStringOutput(),
			WorkloadGroup: &cdwdoris.WorkloadGroupWorkloadGroupArgs{
				WorkloadGroupName:      pulumi.String("example"),
				CpuShare:               pulumi.Int(1024),
				MemoryLimit:            pulumi.Int(20),
				EnableMemoryOverCommit: pulumi.Bool(true),
				CpuHardLimit:           pulumi.String("30%"),
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
