```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const gz = tencentcloud.availability.getZonesByProduct({
    name: "ap-guangzhou-6",
    product: "ckafka",
});
// create vpc
const vpc = new tencentcloud.vpc.Instance("vpc", {
    name: "vpc",
    cidrBlock: "10.0.0.0/16",
});
// create vpc subnet
const subnet = new tencentcloud.subnet.Instance("subnet", {
    name: "subnet",
    vpcId: vpc.id,
    availabilityZone: "ap-guangzhou-6",
    cidrBlock: "10.0.20.0/28",
    isMulticast: false,
});
// create ckafka
const example = new tencentcloud.ckafka.Instance("example", {
    instanceName: "tf-example",
    zoneId: output(gz.then(gz => gz.zones?.[0]?.id)).apply(x =>Number(x)),
    period: 1,
    vpcId: vpc.id,
    subnetId: subnet.id,
    msgRetentionTime: 1300,
    renewFlag: 0,
    kafkaVersion: "2.8.1",
    diskSize: 200,
    diskType: "CLOUD_BASIC",
    bandWidth: 40,
    partition: 400,
    specificationsType: "profession",
    instanceType: 1,
    config: {
        autoCreateTopicEnable: true,
        defaultNumPartitions: 3,
        defaultReplicationFactor: 3,
    },
    dynamicRetentionConfig: {
        enable: 1,
    },
    deleteProtectionEnable: 1,
});
