	pulumi.Run(func(ctx *pulumi.Context) error {
		gz, err := availability.GetZonesByProduct(ctx, &availability.GetZonesByProductArgs{
			Name:    pulumi.StringRef("ap-guangzhou-6"),
			Product: "ckafka",
		}, nil)
		if err != nil {
			return err
		}
		// create vpc
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc"),
			CidrBlock: pulumi.String("10.0.0.0/16"),
		})
		if err != nil {
			return err
		}
		// create vpc subnet
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			Name:             pulumi.String("subnet"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			AvailabilityZone: pulumi.String("ap-guangzhou-6"),
			CidrBlock:        pulumi.String("10.0.20.0/28"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create ckafka
		_, err = ckafka.NewInstance(ctx, "example", &ckafka.InstanceArgs{
			InstanceName:       pulumi.String("tf-example"),
			ZoneId:             pulumi.String(gz.Zones[0].Id),
			Period:             pulumi.Int(1),
