func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		availabilityZone := "ap-guangzhou-6"
		if param := cfg.Get("availabilityZone"); param != "" {
			availabilityZone = param
		}
		// create vpc
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			CidrBlock: pulumi.String("10.0.0.0/16"),
			Name:      pulumi.String("vpc"),
		})
		if err != nil {
			return err
		}
		// create subnet
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			AvailabilityZone: pulumi.String(availabilityZone),
			Name:             pulumi.String("subnet"),
			CidrBlock:        pulumi.String("10.0.1.0/24"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create security group
		example, err := security.NewGroup(ctx, "example", &security.GroupArgs{
			Name:        pulumi.String("tf-example"),
			Description: pulumi.String("sg desc."),
			ProjectId:   pulumi.Int(0),
			Tags: pulumi.StringMap{
				"createBy": pulumi.String("Terraform"),
			},
		})
		if err != nil {
			return err
		}
		// create clb instance
		exampleInstance, err := clb.NewInstance(ctx, "example", &clb.InstanceArgs{
			NetworkType: pulumi.String("INTERNAL"),
			ClbName:     pulumi.String("clb-example"),
			ProjectId:   pulumi.Int(0),
			VpcId:       vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:    subnet2.ID().ToIDOutput().ToStringOutput(),
			Tags: pulumi.StringMap{
				"createBy": pulumi.String("Terraform"),
			},
		})
		if err != nil {
			return err
		}
		// attachment
		_, err = clb.NewSecurityGroupAttachment(ctx, "example", &clb.SecurityGroupAttachmentArgs{
			SecurityGroup:   example.ID().ToIDOutput().ToStringOutput(),
			LoadBalancerIds: exampleInstance.ID().ToIDOutput().ToStringOutput(),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
