    topicName: "tf_example",
    logsetId: example.id,
    autoSplit: false,
    maxSplitPartitions: 20,
    partitionCount: 1,
    period: 30,
    storageType: "hot",
    describes: "Test Demo.",
    hotPeriod: 10,
    tags: {
        test: "test",
    },
});
const tokenizerValue = `@&?|#()='\\\\\\",;:<>[]{}/ \\
\\\\t\\\\r\\\\\\\\
`;
const exampleIndex = new tencentcloud.cls.Index("example", {
    topicId: "abc97756-e620-47a4-aa2b-08561e79f086",
    rule: {
        fullText: {
            caseSensitive: true,
            tokenizer: tokenizerValue,
            containZH: true,
        },
        keyValue: {
            caseSensitive: true,
            keyValues: [
                {
                    key: "key1",
                    value: {
                        containZH: true,
                        sqlFlag: true,
                        tokenizer: tokenizerValue,
                        type: "text",
                        alias: "alias1",
                    },
                },
                {
