## Example Usage

### Create a single availability zone NORMAL CynosDB cluster

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const config = new pulumi.Config();
const availabilityZone = config.get("availabilityZone") || "ap-guangzhou-3";
// create vpc
const vpc = new tencentcloud.vpc.Instance("vpc", {
    name: "vpc",
    cidrBlock: "10.0.0.0/16",
});
// create subnet
const subnet = new tencentcloud.subnet.Instance("subnet", {
    availabilityZone: availabilityZone,
    name: "subnet",
    vpcId: vpc.id,
    cidrBlock: "10.0.20.0/28",
    isMulticast: false,
});
// create security group
const example = new tencentcloud.security.Group("example", {
    name: "tf-example",
    description: "sg desc.",
    projectId: 0,
    tags: {
        example: "test",
    },
});
// create cynosdb cluster
const exampleCluster = new tencentcloud.cynosdb.Cluster("example", {
    availableZone: availabilityZone,
    vpcId: vpc.id,
    subnetId: subnet.id,
    dbMode: "NORMAL",
    dbType: "MYSQL",
    dbVersion: "5.7",
    port: 3306,
    clusterName: "tf-example",
    password: "cynosDB@123",
    instanceMaintainDuration: 7200,
    instanceMaintainStartTime: 10800,
    instanceCpuCore: 2,
    instanceMemorySize: 4,
    forceDelete: false,
    instanceMaintainWeekdays: [
        "Fri",
        "Mon",
        "Sat",
        "Sun",
        "Thu",
        "Wed",
        "Tue",
    ],
    paramItems: [
        {
            name: "character_set_server",
            currentValue: "utf8mb4",
        },
        {
            name: "lower_case_table_names",
            currentValue: "0",
        },
    ],
    rwGroupSgs: [example.id],
    instanceInitInfos: [
        {
            cpu: 2,
            memory: 4,
            instanceType: "rw",
            instanceCount: 1,
            deviceType: "common",
        },
        {
            cpu: 2,
            memory: 4,
            instanceType: "ro",
            instanceCount: 1,
            deviceType: "exclusive",
        },
    ],
    syncWay: "async",
