        final var gz3 = VpcFunctions.getSubnets(GetSubnetsArgs.builder()
            .availabilityZone(defaultAz)
            .isDefault(true)
            .build());

        final var vpcId = gz3.instanceLists()[0].vpcId();

        final var subnetId = gz3.instanceLists()[0].subnetId();

        var readOnlyInstanceExclusiveAccess = new ReadOnlyInstanceExclusiveAccess("readOnlyInstanceExclusiveAccess", ReadOnlyInstanceExclusiveAccessArgs.builder()
            .clusterId(cynosdbClusterId)
            .instanceId(cynosdbClusterInstanceId)
            .vpcId(vpcId)
            .subnetId(subnetId)
            .port(1234)
            .securityGroupIds(cynosdbClusterSecurityGroupId)
            .build());

    }
}
