			Filters: []instance.GetTypesFilter{
				{
					Name: "instance-charge-type",
					Values: []string{
						"POSTPAID_BY_HOUR",
					},
				},
				{
					Name: "zone",
					Values: []string{
						availabilityZone,
					},
				},
			},
		}, nil)
		if err != nil {
			return err
		}
		emrVpc, err := vpc.NewInstance(ctx, "emr_vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("emr-vpc"),
			CidrBlock: pulumi.String("10.0.0.0/16"),
