			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		emrSg, err := security.NewGroup(ctx, "emr_sg", &security.GroupArgs{
			Name:        pulumi.String("emr-sg"),
			Description: pulumi.String("emr sg"),
			ProjectId:   pulumi.Int(0),
		})
		if err != nil {
			return err
		}
		_, err = emr.NewCluster(ctx, "emr_cluster", &emr.ClusterArgs{
			ProductId: pulumi.Int(38),
			VpcSettings: pulumi.StringMap{
