					Cpu:         pulumi.Int(4),
					DiskSize:    pulumi.Int(100),
					DiskType:    pulumi.String("CLOUD_PREMIUM"),
					Spec:        pulumi.Sprintf("CVM.%v", cvm4c8m.InstanceTypes[0].Family),
