    name: "tf-example",
    clusterId: example.id,
    maxSize: 6,
    minSize: 1,
    vpcId: vpc.then(vpc => vpc.instanceLists?.[0]?.vpcId),
    subnetIds: [vpc.then(vpc => vpc.instanceLists?.[0]?.subnetId)],
    retryPolicy: "INCREMENTAL_INTERVALS",
    desiredCapacity: 4,
    enableAutoScale: true,
