        test2: "test2",
    },
    taints: [
        {
            key: "test_taint",
            value: "taint_value",
            effect: "PreferNoSchedule",
        },
        {
            key: "test_taint2",
            value: "taint_value2",
            effect: "PreferNoSchedule",
        },
