## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const firewallTemplate = new tencentcloud.lighthouse.FirewallTemplate("firewall_template", {templateName: "empty-template"});
const lighthouse = new tencentcloud.lighthouse.Instance("lighthouse", {
    bundleId: "bundle2022_gen_01",
    blueprintId: "lhbp-f1lkcd41",
    period: 1,
    renewFlag: "NOTIFY_AND_AUTO_RENEW",
    instanceName: "hello world",
    zone: "ap-guangzhou-3",
    containers: [
        {
            containerImage: "ccr.ccs.tencentyun.com/qcloud/nginx",
            containerName: "nginx",
            envs: [
                {
                    key: "key",
                    value: "value",
                },
                {
                    key: "key2",
                    value: "value2",
                },
            ],
            publishPorts: [
                {
                    hostPort: 80,
                    containerPort: 80,
                    ip: "127.0.0.1",
                    protocol: "tcp",
                },
                {
                    hostPort: 36000,
                    containerPort: 36000,
                    ip: "127.0.0.1",
                    protocol: "tcp",
                },
            ],
            volumes: [
                {
                    containerPath: "/data",
                    hostPath: "/tmp",
                },
                {
                    containerPath: "/var",
                    hostPath: "/tmp",
                },
            ],
            command: "ls -l",
        },
        {
            containerImage: "ccr.ccs.tencentyun.com/qcloud/resty",
            containerName: "resty",
            envs: [{
                key: "key2",
                value: "value2",
            }],
            publishPorts: [{
                hostPort: 80,
                containerPort: 80,
                ip: "127.0.0.1",
                protocol: "udp",
            }],
            volumes: [{
                containerPath: "/var",
                hostPath: "/tmp",
            }],
            command: "echo \"hello\"",
        },
    ],
    firewallTemplateId: firewallTemplate.id,
});
