tencentcloud:Mqtt/instance:Instance.description:
Provides a resource to create a MQTT instance

## Example Usage

### Create a POSTPAID instance

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const config = new pulumi.Config();
const availabilityZone = config.get("availabilityZone") || "ap-guangzhou-6";
// create vpc
const vpc = new tencentcloud.vpc.Instance("vpc", {
    cidrBlock: "10.0.0.0/16",
    name: "vpc",
});
// create subnet
const subnet = new tencentcloud.subnet.Instance("subnet", {
    vpcId: vpc.id,
    availabilityZone: availabilityZone,
    name: "subnet",
    cidrBlock: "10.0.1.0/24",
    isMulticast: false,
});
// create mqtt instance
const example = new tencentcloud.mqtt.Instance("example", {
    instanceType: "PRO",
    name: "tf-example",
    skuCode: "pro_6k_1",
    remark: "remarks.",
    vpcList: {
        vpcId: vpc.id,
        subnetId: subnet.id,
    },
    payMode: 0,
    x509Mode: "BYOC",
    deviceCertificateProvisionType: "JITP",
    messageRate: 100,
    useDefaultServerCert: true,
    tags: {
        createBy: "Terraform",
    },
});
```
