package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/availability"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/mysql"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/security"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/subnet"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/vpc"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		zones, err := availability.GetZonesByProduct(ctx, &availability.GetZonesByProductArgs{
			Product: "cdb",
		}, nil)
		if err != nil {
			return err
		}
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc-mysql"),
			CidrBlock: pulumi.String("10.0.0.0/16"),
		})
		if err != nil {
			return err
		}
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			AvailabilityZone: pulumi.String(zones.Zones[0].Name),
			Name:             pulumi.String("subnet-mysql"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("10.0.0.0/16"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		securityGroup, err := security.NewGroup(ctx, "security_group", &security.GroupArgs{
			Name:        pulumi.String("sg-mysql"),
			Description: pulumi.String("mysql test"),
		})
		if err != nil {
			return err
		}
		example, err := mysql.NewInstance(ctx, "example", &mysql.InstanceArgs{
			InternetService:  pulumi.Int(1),
			EngineVersion:    pulumi.String("5.7"),
			ChargeType:       pulumi.String("POSTPAID"),
			RootPassword:     pulumi.String("PassWord123"),
			SlaveDeployMode:  pulumi.Int(0),
			AvailabilityZone: pulumi.String(zones.Zones[0].Name),
			SlaveSyncMode:    pulumi.Int(1),
			InstanceName:     pulumi.String("tf-example-mysql"),
			MemSize:          pulumi.Int(4000),
			VolumeSize:       pulumi.Int(200),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			IntranetPort:     pulumi.Int(3306),
			SecurityGroups: pulumi.StringArray{
				securityGroup.ID().ToIDOutput().ToStringOutput(),
			},
			Tags: pulumi.StringMap{
				"name": pulumi.String("test"),
			},
			Parameters: pulumi.StringMap{
				"character_set_server": pulumi.String("utf8"),
				"max_connections":      pulumi.String("1000"),
			},
		})
		if err != nil {
			return err
		}
		_, err = mysql.NewRemoteBackupConfig(ctx, "example", &mysql.RemoteBackupConfigArgs{
			InstanceId:       example.ID().ToIDOutput().ToStringOutput(),
			RemoteBackupSave: pulumi.String("on"),
			RemoteBinlogSave: pulumi.String("on"),
			RemoteRegions: pulumi.StringArray{
				pulumi.String("ap-shanghai"),
			},
			ExpireDays: pulumi.Int(7),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
