			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("10.0.0.0/16"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		securityGroup, err := security.NewGroup(ctx, "security_group", &security.GroupArgs{
			Name:        pulumi.String("sg-mysql"),
			Description: pulumi.String("mysql test"),
		})
		if err != nil {
			return err
		}
		exampleInstance, err := mysql.NewInstance(ctx, "example", &mysql.InstanceArgs{
			InternetService:  pulumi.Int(1),
			EngineVersion:    pulumi.String("5.7"),
			ChargeType:       pulumi.String("POSTPAID"),
			RootPassword:     pulumi.String("PassWord123"),
			SlaveDeployMode:  pulumi.Int(0),
			AvailabilityZone: pulumi.String(zones.Zones[1].Name),
			SlaveSyncMode:    pulumi.Int(1),
			InstanceName:     pulumi.String("tf-example-mysql"),
			MemSize:          pulumi.Int(4000),
			VolumeSize:       pulumi.Int(200),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			IntranetPort:     pulumi.Int(3306),
			SecurityGroups: pulumi.StringArray{
				securityGroup.ID().ToIDOutput().ToStringOutput(),
			},
			Tags: pulumi.StringMap{
				"name": pulumi.String("test"),
			},
			Parameters: pulumi.StringMap{
				"character_set_server": pulumi.String("utf8"),
				"max_connections":      pulumi.String("1000"),
			},
		})
		if err != nil {
			return err
		}
		example := mysql.GetInstanceOutput(ctx, mysql.GetInstanceOutputArgs{
			MysqlId: exampleInstance.ID().ToIDOutput().ToStringOutput(),
		}, nil)
		_, err = mysql.NewReadonlyInstance(ctx, "example", &mysql.ReadonlyInstanceArgs{
			MasterInstanceId: exampleInstance.ID().ToIDOutput().ToStringOutput(),
			InstanceName:     pulumi.String("tf-mysql"),
			MemSize:          pulumi.Int(2000),
			VolumeSize:       pulumi.Int(200),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			IntranetPort:     pulumi.Int(3306),
			SecurityGroups: pulumi.StringArray{
				securityGroup.ID().ToIDOutput().ToStringOutput(),
			},
			Tags: pulumi.StringMap{
				"createBy": pulumi.String("terraform"),
			},
		})
		if err != nil {
			return err
		}
		_, err = mysql.NewRoGroupLoadOperation(ctx, "ro_group_load_operation", &mysql.RoGroupLoadOperationArgs{
