)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		availabilityZone := "ap-guangzhou-3"
		if param := cfg.Get("availabilityZone"); param != "" {
			availabilityZone = param
		}
		// create vpc
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc"),
			CidrBlock: pulumi.String("10.0.0.0/16"),
		})
		if err != nil {
			return err
		}
		// create vpc subnet
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			AvailabilityZone: pulumi.String(availabilityZone),
			Name:             pulumi.String("subnet"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("10.0.20.0/28"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create postgresql instance
		example, err := postgresql.NewInstance(ctx, "example", &postgresql.InstanceArgs{
			Name:             pulumi.String("example"),
			AvailabilityZone: pulumi.String(availabilityZone),
			ChargeType:       pulumi.String("POSTPAID_BY_HOUR"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			DbMajorVersion:   pulumi.String("10"),
			EngineVersion:    pulumi.String("10.23"),
			RootUser:         pulumi.String("root123"),
			RootPassword:     pulumi.String("Root123$"),
			Charset:          pulumi.String("UTF8"),
			ProjectId:        pulumi.Int(0),
			Cpu:              pulumi.Int(1),
			Memory:           pulumi.Int(2),
			Storage:          pulumi.Int(10),
			Tags: pulumi.StringMap{
				"test": pulumi.String("tf"),
			},
		})
		if err != nil {
			return err
		}
		// create postgresql account
		exampleAccount, err := postgresql.NewAccount(ctx, "example", &postgresql.AccountArgs{
			DbInstanceId: example.ID().ToIDOutput().ToStringOutput(),
			UserName:     pulumi.String("tf_example"),
			Password:     pulumi.String("Password@123"),
			Type:         pulumi.String("normal"),
			Remark:       pulumi.String("remark"),
			LockStatus:   pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// create postgresql database
		_, err = postgresql.NewDatabase(ctx, "example", &postgresql.DatabaseArgs{
			DbInstanceId:  example.ID().ToIDOutput().ToStringOutput(),
			DatabaseName:  pulumi.String("test_db"),
			DatabaseOwner: exampleAccount.UserName,
			Encoding:      pulumi.String("UTF8"),
			Collate:       pulumi.String("C"),
			Ctype:         pulumi.String("C"),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
