	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/vpc"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		zone, err := redis.GetZoneConfig(ctx, &redis.GetZoneConfigArgs{
			TypeId: pulumi.IntRef(7),
			Region: pulumi.StringRef("ap-guangzhou"),
		}, nil)
		if err != nil {
			return err
		}
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			CidrBlock: pulumi.String("10.0.0.0/16"),
			Name:      pulumi.String("tf_redis_vpc"),
		})
		if err != nil {
			return err
		}
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			AvailabilityZone: pulumi.String(zone.Lists[2].Zone),
			Name:             pulumi.String("tf_redis_subnet"),
			CidrBlock:        pulumi.String("10.0.1.0/24"),
		})
		if err != nil {
			return err
		}
		securityGroup, err := security.NewGroup(ctx, "security_group", &security.GroupArgs{
			Name: pulumi.String("tf-redis-sg"),
		})
		if err != nil {
			return err
		}
		example, err := tencentcloud.NewSecurityGroupLiteRule(ctx, "example", &tencentcloud.SecurityGroupLiteRuleArgs{
			SecurityGroupId: securityGroup.ID(),
			Ingresses: []string{
				"ACCEPT#192.168.1.0/24#80#TCP",
				"DROP#8.8.8.8#80,90#UDP",
				"DROP#0.0.0.0/0#80-90#TCP",
			},
			Egresses: []string{
				"ACCEPT#192.168.0.0/16#ALL#TCP",
				"ACCEPT#10.0.0.0/8#ALL#ICMP",
				"DROP#0.0.0.0/0#ALL#ALL",
			},
		})
		if err != nil {
			return err
		}
		exampleInstance, err := redis.NewInstance(ctx, "example", &redis.InstanceArgs{
			AvailabilityZone: pulumi.String(zone.Lists[2].Zone),
			TypeId:           pulumi.Int(zone.Lists[2].TypeId),
			Password:         pulumi.String("Password@123"),
			MemSize:          pulumi.Int(8192),
			RedisShardNum:    pulumi.Int(zone.Lists[2].RedisShardNums[0]),
			RedisReplicasNum: pulumi.Int(zone.Lists[2].RedisReplicasNums[0]),
			Name:             pulumi.String("tf_example"),
			Port:             pulumi.Int(6379),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			SecurityGroups: pulumi.StringArray{
				securityGroup.ID().ToIDOutput().ToStringOutput(),
			},
		})
		if err != nil {
			return err
		}
		_, err = redis.NewSecurityGroupAttachment(ctx, "example", &redis.SecurityGroupAttachmentArgs{
			InstanceId:      exampleInstance.ID().ToIDOutput().ToStringOutput(),
			SecurityGroupId: example.Id,
		})
		if err != nil {
			return err
		}
		return nil
	})
}
