import com.pulumi.tencentcloud.Sqlserver.DbArgs;
import com.pulumi.tencentcloud.Sqlserver.ConfigDatabaseCdc;
import com.pulumi.tencentcloud.Sqlserver.ConfigDatabaseCdcArgs;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        final var zones = AvailabilityFunctions.getZonesByProduct(GetZonesByProductArgs.builder()
            .product("sqlserver")
            .build());

        var vpc = new com.pulumi.tencentcloud.Vpc.Instance("vpc", com.pulumi.tencentcloud.Vpc.InstanceArgs.builder()
            .name("vpc-example")
            .cidrBlock("10.0.0.0/16")
            .build());

        var subnet = new com.pulumi.tencentcloud.Subnet.Instance("subnet", com.pulumi.tencentcloud.Subnet.InstanceArgs.builder()
            .availabilityZone(zones.zones()[4].name())
            .name("subnet-example")
            .vpcId(vpc.id())
            .cidrBlock("10.0.0.0/16")
            .isMulticast(false)
            .build());

        var securityGroup = new Group("securityGroup", GroupArgs.builder()
            .name("sg-example")
            .description("desc.")
            .build());

        var example = new BasicInstance("example", BasicInstanceArgs.builder()
            .name("tf-example")
            .availabilityZone(zones.zones()[4].name())
            .chargeType("POSTPAID_BY_HOUR")
            .vpcId(vpc.id())
            .subnetId(subnet.id())
            .projectId(0)
            .memory(4)
            .storage(100)
            .cpu(2)
            .machineType("CLOUD_PREMIUM")
            .maintenanceWeekSets(            
                1,
                2,
                3)
            .maintenanceStartTime("09:00")
            .maintenanceTimeSpan(3)
            .securityGroups(securityGroup.id())
            .tags(Map.of("test", "test"))
            .build());

        var exampleDb = new Db("exampleDb", DbArgs.builder()
            .instanceId(example.id())
            .name("tf_example_db")
            .charset("Chinese_PRC_BIN")
            .remark("test-remark")
            .build());

        var exampleConfigDatabaseCdc = new ConfigDatabaseCdc("exampleConfigDatabaseCdc", ConfigDatabaseCdcArgs.builder()
            .instanceId(example.id())
            .dbName(exampleDb.name())
            .modifyType("disable")
            .build());

    }
}
