		}
		_, err = sqlserver.NewConfigDatabaseMdf(ctx, "example", &sqlserver.ConfigDatabaseMdfArgs{
			DbName:     exampleDb.Name,
			InstanceId: example.ID().ToIDOutput().ToStringOutput(),
		})
		if err != nil {
			return err
		}
		return nil
	})
