package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/availability"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/security"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/sqlserver"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/subnet"
	"github.com/tencentcloudstack/pulumi-tencentcloud/sdk/go/tencentcloud/vpc"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		zones, err := availability.GetZonesByProduct(ctx, &availability.GetZonesByProductArgs{
			Product: "sqlserver",
		}, nil)
		if err != nil {
			return err
		}
		vpc2, err := vpc.NewInstance(ctx, "vpc", &vpc.InstanceArgs{
			Name:      pulumi.String("vpc-example"),
			CidrBlock: pulumi.String("10.0.0.0/16"),
		})
		if err != nil {
			return err
		}
		subnet2, err := subnet.NewInstance(ctx, "subnet", &subnet.InstanceArgs{
			AvailabilityZone: pulumi.String(zones.Zones[4].Name),
			Name:             pulumi.String("subnet-example"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			CidrBlock:        pulumi.String("10.0.0.0/16"),
			IsMulticast:      pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		securityGroup, err := security.NewGroup(ctx, "security_group", &security.GroupArgs{
			Name:        pulumi.String("sg-example"),
			Description: pulumi.String("desc."),
		})
		if err != nil {
			return err
		}
		exampleBasicInstance, err := sqlserver.NewBasicInstance(ctx, "example", &sqlserver.BasicInstanceArgs{
			Name:             pulumi.String("tf-example"),
			AvailabilityZone: pulumi.String(zones.Zones[4].Name),
			ChargeType:       pulumi.String("POSTPAID_BY_HOUR"),
			VpcId:            vpc2.ID().ToIDOutput().ToStringOutput(),
			SubnetId:         subnet2.ID().ToIDOutput().ToStringOutput(),
			ProjectId:        pulumi.Int(0),
			Memory:           pulumi.Int(4),
			Storage:          pulumi.Int(100),
			Cpu:              pulumi.Int(2),
			MachineType:      pulumi.String("CLOUD_PREMIUM"),
			MaintenanceWeekSets: pulumi.IntArray{
				pulumi.Int(1),
				pulumi.Int(2),
				pulumi.Int(3),
			},
			MaintenanceStartTime: pulumi.String("09:00"),
			MaintenanceTimeSpan:  pulumi.Int(3),
			SecurityGroups: pulumi.StringArray{
				securityGroup.ID().ToIDOutput().ToStringOutput(),
			},
			Tags: pulumi.StringMap{
				"test": pulumi.String("test"),
			},
		})
		if err != nil {
			return err
		}
		exampleDb, err := sqlserver.NewDb(ctx, "example", &sqlserver.DbArgs{
			InstanceId: exampleBasicInstance.ID().ToIDOutput().ToStringOutput(),
			Name:       pulumi.String("tf_example_db"),
			Charset:    pulumi.String("Chinese_PRC_BIN"),
			Remark:     pulumi.String("test-remark"),
		})
		if err != nil {
			return err
		}
		exampleGeneralBackup, err := sqlserver.NewGeneralBackup(ctx, "example", &sqlserver.GeneralBackupArgs{
			InstanceId: exampleDb.InstanceId,
			BackupName: pulumi.String("tf_example_backup"),
			Strategy:   pulumi.Int(0),
		})
		if err != nil {
			return err
		}
		example := sqlserver.GetBackupsOutput(ctx, sqlserver.GetBackupsOutputArgs{
			InstanceId: exampleDb.InstanceId,
			BackupName: exampleGeneralBackup.BackupName,
			StartTime:  pulumi.String("2023-07-25 00:00:00"),
			EndTime:    pulumi.String("2023-08-04 00:00:00"),
		}, nil)
		_, err = sqlserver.NewFullBackupMigration(ctx, "example", &sqlserver.FullBackupMigrationArgs{
			InstanceId:    exampleGeneralBackup.InstanceId,
			RecoveryType:  pulumi.String("FULL"),
			UploadType:    pulumi.String("COS_URL"),
			MigrationName: pulumi.String("migration_test"),
			BackupFiles: pulumi.StringArray{
				example.ApplyT(func(example sqlserver.GetBackupsResult) (*string, error) {
					return example.Lists[0].InternetUrl, nil
				}).(pulumi.StringPtrOutput),
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
