			Privilege:   pulumi.String("ReadWrite"),
		})
		if err != nil {
			return err
		}
		_, err = sqlserver.NewMigration(ctx, "migration", &sqlserver.MigrationArgs{
			MigrateName: pulumi.String("tf_test_migration"),
