		if err != nil {
			return err
		}
		_, err = sqlserver.NewReadonlyInstance(ctx, "example", &sqlserver.ReadonlyInstanceArgs{
			Name:              pulumi.String("tf_example"),
			AvailabilityZone:  pulumi.String(zones.Zones[4].Name),
