tencentcloud:Tcr/replication:Replication.description:
Provides a resource to create and update a TCR replication

## Example Usage

### Sync source tcr instance to target instance

Synchronize an existing tcr instance to the destination instance. This operation is often used in the cross-multiple region scenario.
Assume you have had two TCR instances before this operation. This example shows how to sync a tcr instance from ap-guangzhou(gz) to ap-shanghai(sh).

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as std from "@pulumi/std";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

// tcr instance on ap-guangzhou
const exampleGz = new tencentcloud.tcr.Instance("example_gz", {
    name: "tf-example-tcr-gz",
    instanceType: "premium",
    tags: {
        createdBy: "terraform",
    },
});
const exampleGzNamespace = new tencentcloud.tcr.Namespace("example_gz", {
    instanceId: exampleGz.id,
    name: "tf_example_ns_gz",
    isPublic: true,
    isAutoScan: true,
    isPreventVul: true,
    severity: "medium",
    cveWhitelistItems: [{
        cveId: "cve-xxxxx",
    }],
});
// tcr instance on ap-shanghai
const exampleSh = new tencentcloud.tcr.Instance("example_sh", {
    name: "tf-example-tcr-sh",
    instanceType: "premium",
    deleteBucket: true,
});
const exampleShNamespace = new tencentcloud.tcr.Namespace("example_sh", {
    instanceId: exampleSh.id,
    name: "tf_example_ns_sh",
    isPublic: true,
    isAutoScan: true,
    isPreventVul: true,
    severity: "medium",
    cveWhitelistItems: [{
        cveId: "cve-xxxxx",
    }],
});
const example = new tencentcloud.tcr.Replication("example", {
    sourceRegistryId: exampleGz.id,
    destinationRegistryId: exampleSh.id,
    rule: {
        name: "tf-example",
        destNamespace: exampleShNamespace.name,
        override: true,
        deletion: true,
        filters: [{
            type: "name",
            value: std.joinOutput({
                separator: "/",
                input: [
                    exampleGzNamespace.name,
                    "**",
                ],
            }).result,
        }],
    },
    destinationRegionId: 1,
    description: "remark.",
});
