import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        var example = new SecurityJsInjectionRule("example", SecurityJsInjectionRuleArgs.builder()
            .zoneId("zone-3fkff38fyw8s")
            .jsInjectionRules(SecurityJsInjectionRuleJsInjectionRulesArgs.builder()
                .name("tf-example")
                .priority(50)
                .condition("${http.request.host} in ['www.demo.com']")
                .injectJs("inject-sdk-only")
                .build())
            .build());

    }
}
