			Name:        pulumi.String("tf-example"),
			Description: pulumi.String("security group desc."),
			Tags: pulumi.StringMap{
				"createBy": pulumi.String("Terraform"),
			},
		})
		if err != nil {
			return err
		}
		// create thpc workspaces
		_, err = thpc.NewWorkspaces(ctx, "example", &thpc.WorkspacesArgs{
			SpaceName:       pulumi.String("tf-example"),
			SpaceChargeType: pulumi.String("PREPAID"),
			SpaceType:       pulumi.String("96A.96XLARGE2304"),
			HpcClusterId:    pulumi.String("hpc-l9anqcbl"),
			ImageId:         pulumi.String(images2.Images[0].ImageId),
			SecurityGroupIds: pulumi.StringArray{
				example.ID().ToIDOutput().ToStringOutput(),
			},
			Placement: &thpc.WorkspacesPlacementArgs{
				Zone:      pulumi.String(availabilityZone),
				ProjectId: pulumi.Int(0),
			},
			SpaceChargePrepaid: &thpc.WorkspacesSpaceChargePrepaidArgs{
				Period:    pulumi.Int(1),
				RenewFlag: pulumi.String("NOTIFY_AND_AUTO_RENEW"),
			},
			SystemDisk: &thpc.WorkspacesSystemDiskArgs{
				DiskSize: pulumi.Int(100),
