```typescript
import * as pulumi from "@pulumi/pulumi";
import * as tencentcloud from "@tencentcloud_iac/pulumi";

const example = new tencentcloud.waf.CustomWhiteRule("example", {
    name: "tf-example",
    sortId: "30",
    expireTime: "0",
    strategies: [
        {
            field: "IP",
            compareFunc: "ipmatch",
            content: "1.1.1.1",
            arg: "",
        },
        {
            field: "IP_GEO",
            compareFunc: "geo_in",
            content: JSON.stringify({
                Lang: "cn",
                Areas: [{
                    Country: "国外",
                }],
            }),
            arg: "",
        },
    ],
    status: "1",
    domain: "www.demo.com",
    bypass: "geoip,cc,owasp",
    logicalOp: "and",
});
